// DE VELDLAAG van de bewerkstand: welk predicaat draagt de getoonde waarde, wat
// een save met een MEERTALIG veld doet, en wat er als IRI de graaf in mag.
//
// Gedragsbron: het fase C-taak 5-blok in viewer-bevroren/assets/doc.js — `dragendPred`,
// `geldigeIriTekst` — plus `voldoetAanPatroon` uit het formulierblok
// (r.8940-8970). Daar staan ze tussen de renderfuncties en lezen ze `state.store` rechtstreeks;
// hier krijgen ze de store als eerste argument, zodat ze DOM-vrij en in node
// toetsbaar zijn — dezelfde afspraak als de rest van src/model/.
//
// WAT HIER WEL EN NIET STAAT. `setLiteral` in edit.js is de kale bewerking:
// alle waarden van (subject, pred) eruit, één nieuwe erin. Dat is precies wat
// een meertalig veld NIET mag doen — en dáárvoor bestaat `zetLiteral`. Die
// stond hier ooit met een eigen body naast een tweede kopie in edit.js; sinds
// de fixronde van golf B (review I-5) staat hij één keer, in edit.js, en geeft
// deze module hem door. Wat hier BLIJFT is de laag die over de WEERGAVE gaat en
// niet over de serialisatie: welk predicaat de getoonde waarde draagt, wat er
// als IRI of onder een sh:pattern de graaf in mag, en welke tekst een
// IRI-combobox toont. De termdecoder (`termVan`) is dezelfde weg gegaan als
// `zetLiteral` en woont nu in de leaf `model/term.js`.
import * as N3 from 'n3';
import { PREFIXES } from './parse.js';
import { termVan as termVanIntern } from './term.js';

const { namedNode } = N3.DataFactory;

const DCT = PREFIXES.dct;
const RDFS = PREFIXES.rdfs;
const XSD = PREFIXES.xsd;

/** De voorkeursvolgorde voor een TITEL. Een verplichting draagt haar naam op
 *  rdfs:label (zo leest parse.js hem, zo schrijft addDuty hem); dct:title als
 *  enige keuze zou daar een tweede naam naast de bestaande zetten. */
export const TITEL_PREDS = [DCT + 'title', RDFS + 'label'];
/** Idem voor een TOELICHTING/beschrijving. */
export const TOELICHT_PREDS = [DCT + 'description', RDFS + 'comment'];
/** De vorm waarin een leeg datumveld wordt weggeschreven. Zonder datatype zou
 *  een bewerkte datum een kale string worden en uit de datumsortering vallen. */
export const DATUM_STANDAARD = { datatype: XSD + 'date' };

/** DE TERMDECODER, doorgegeven uit `model/term.js`.
 *
 *  Hij stond hier met een eigen body, naast een tweede body in
 *  `ui/bewerk/integratie/anker.ts` die op VIJF van zes ingangen een ander
 *  antwoord gaf (eindreview I-1) — en naast nog negen losse decodeerplekken.
 *  Sinds de consolidatie staat de tabel één keer, in de leaf `model/term.js`,
 *  en geeft deze module hem door: dezelfde afspraak als bij `zetLiteral`
 *  hieronder, en om dezelfde reden — de UI-kant haalt alles wat met velden te
 *  maken heeft uit déze module. Wie de tabel zelf wil lezen, leest `term.js`. */
export { termVan } from './term.js';

const alsTerm = termVanIntern;

/** WELK PREDICAAT DRAAGT DE GETOONDE WAARDE? De modellezer valt terug (een
 *  titel is dct:title óf rdfs:label). Schrijven naar het eerste terwijl de
 *  waarde uit het tweede komt, laat de bewerking stilzwijgend niets doen: bij
 *  het herlezen wint de oude waarde. Dus: schrijf naar het predicaat dat de
 *  knoop AL draagt, en anders naar het voorkeurspredicaat. */
export function dragendPred(store, termOrIri, preds) {
  if (!store || !termOrIri) return preds[0];
  const t = alsTerm(termOrIri);
  if (!t) return preds[0];
  for (const p of preds) {
    if (store.getQuads(t, namedNode(p), null, null).length) return p;
  }
  return preds[0];
}

/** DE DRIE GEDEDUPLICEERDE VORMEN, doorgegeven uit `edit.js` (review I-5).
 *
 *  `zetLiteral`, `getoondeLiteral` en `literalVorm` stonden hier ook, met een
 *  eigen body en — voor `zetLiteral` — een eigen handtekening. Twee lanes van
 *  golf B hadden ze onafhankelijk uit dezelfde bron (doc.js r.1736-1794)
 *  gebouwd, en omdat de kopieen in verschillende bestanden landden gaf dat geen
 *  merge-conflict: de drift kwam er stil in. Zij staan nu een keer, in de
 *  modellaag naast `setLiteral`, waar de kale bewerking ook woont.
 *
 *  WAT DEZE MODULE DAN NOG IS: de VELDLAAG erboven — welk predicaat de getoonde
 *  waarde draagt, en wat er als IRI of onder een sh:pattern de graaf in mag.
 *  Die vragen gaan over de weergave en niet over de serialisatie, en daarom
 *  staan ze hier apart.
 *
 *  De doorgifte is er zodat de UI-kant een ingang houdt: `kaartveld.tsx` en de
 *  veldtests halen alles wat met velden te maken heeft uit deze module. Wie de
 *  bewerking zelf wil lezen, leest `edit.js`. */
export { getoondeLiteral, literalVorm, zetLiteral } from './edit.js';

/** WAT MAG ER ALS IRI DE GRAAF IN — DOORGEGEVEN uit `edit.js`.
 *
 *  Hij stond hier voluit, en dat was de goede plek zolang alleen VELDEN een IRI
 *  schreven. Sinds `hernoemKnoop` een IRI als SUBJECT schrijft, moet de
 *  mutatielaag zelf kunnen weigeren (een ongeldige subject-IRI maakt de bron
 *  onleesbaar), en dan hoort de toets daar te wonen — naast `expandIri` en
 *  `mintIri`. De reden staat er voluit bij. Deze doorgifte houdt de veldlaag de
 *  ingang die zij altijd was: `kaartveld.tsx`, de sloteditor en de veldtests
 *  halen hem hier op, precies zoals `zetLiteral` hierboven. */
export { geldigeIriTekst } from './edit.js';

/** sh:pattern is een ANCHOR-vrije regex (zo leest SHACL hem): geen impliciete
 *  ^…$. Een LEGE waarde slaat deze toets over — sh:pattern zegt niets over
 *  AFWEZIGHEID, alleen over de vorm van een waarde die er wél is; leegmaken
 *  blijft dus altijd toegestaan. Een patroon dat deze JS-regexmotor niet aankan
 *  (SHACL staat XPath-regex toe) mag geen bewerking blokkeren die de gebruiker
 *  verder niets kan schelen: dan geen oordeel. */
export function voldoetAanPatroon(waarde, patroon) {
  if (!patroon || waarde === '') return true;
  try { return new RegExp(patroon).test(waarde); } catch { return true; }
}
