// DE TWEE PRIMITIEVEN van de bewerklaag: één knopje en één rijtje knopjes.
//
// Gedragsbron: `knop` en `editbar` in viewer-bevroren/assets/bewerk-ui.js. Ze staan hier
// apart omdat zowel de ontgrendel-dialoog als (in golf B) de sloteditor en de
// formulierknoppen ze dragen; dezelfde afweging als waarom ze in de bevroren
// viewer bovenaan bewerk-ui.js staan.
//
// GEEN EMOJI ALS LABEL: net als in de bronnenbalk valt een emoji op een systeem
// zonder emoji-font terug op een leeg blokje. De aanroeper kiest een tekstlabel
// of een teken uit de gewone tekstfonts (✕, ⤓, ✎).
//
// stopPropagation/preventDefault is geen detail: deze knopjes staan in
// <summary>-koppen en op rijen die bij elke klik open- of dichtklappen. Zonder
// dat zou elke bewerkactie de kaart eronder omklappen. `on:click` en niet
// `onClick`, om de reden die in strook.tsx voluit staat: Solid delegeert click
// naar het document, en dan is er geen target-fase meer om in te stoppen.
import type { JSX } from 'solid-js';
import './bewerk.css';

export function Knop(props: {
  label: string;
  onClick: (e?: Event) => void;
  cls?: string;
  ariaLabel?: string;
  titel?: string;
}): JSX.Element {
  return (
    <button
      type="button"
      class={['edit-knop', props.cls || ''].filter(Boolean).join(' ')}
      title={props.titel}
      aria-label={props.ariaLabel}
      on:click={(e: MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        props.onClick(e);
      }}
    >{props.label}</button>
  );
}

/** Een rijtje bewerk-knoppen als één balkje. Lege plekken (`null`) vallen weg,
 *  zodat de aanroeper voorwaardelijke knoppen inline kan neerzetten. */
export function Editbar(props: { children?: JSX.Element }): JSX.Element {
  return <span class="editbar">{props.children}</span>;
}
