// HET INLINE LITERAL-VELD EN DE IRI-COMBOBOX.
//
// Gedragsbron: `inlineVeld` en `iriCombobox` in viewer-bevroren/assets/bewerk-ui.js
// (fase C taak 5, plus de fix-ronde die de `verwerkt`-vlag en de Escape-laag
// bracht). De redenen staan daar voluit; hieronder staat wat de vertaling naar
// Solid ANDERS maakt, en waarom de Escape-les bindend blijft.
//
// PUUR: geen store-writes. `onSave`/`onPick` zijn de callbacks van de
// aanroeper; deze module weet niet wat er met de waarde gebeurt.
//
// DE ESCAPE-LES VAN FASE C IS BINDEND, en zij is in Solid alleen te houden met
// `on:keydown` (een echte listener op het element) in plaats van `onKeyDown`
// (Solid delegeert die naar het document). Een Escape in een veld is van dat
// veld: hij annuleert de invoer en gaat niet verder. Er hangen document-brede
// Escape-listeners aan de pagina (invulling-paneel, sectiefilter, zijnav),
// allemaal in de bubbelfase; stoppen in de TARGET-fase volstaat om ze te
// bereiken — maar alléén als de listener echt op het veld zit, want een
// gedelegeerde handler draait pas als de gebeurtenis het document al bereikt
// heeft. De enige laag die nog VÓÓR dit veld kiest is de sleep-annulering
// (capture), en die vuurt alleen tijdens een sleep, waarbij geen veld openstaat.
import { For, Show, createSignal, createEffect, on, onMount } from 'solid-js';
import type { JSX } from 'solid-js';
import { expandIri } from '../../model/edit.js';
import { curie } from '../../model/parse.js';
import { tekst } from '../../stores/weergave.js';
import { herstelLezerplek } from '../lijst/scrollanker.js';
import { Knop } from './knop.jsx';
import './bewerk.css';

/** De haak waarmee het ✎ van de actiestrook hetzelfde veld opent dat hier al
 *  staat. Zonder die haak zou de strook een tweede bewerkroute moeten bouwen
 *  naast deze. */
export type VeldHaak = { openBewerk: () => void };

type Invoerveld = HTMLInputElement | HTMLTextAreaElement;

/** DE CURSOR IN EEN VELD ZETTEN ZONDER DE PAGINA TE VERZETTEN.
 *
 *  Eén helper, en dat is de fix van punt 4 van de testronde (9 sep 2026;
 *  eigenaar: "Als ik klik op nieuwe voorwaarden/toestemmingen etc. springt de
 *  pagina meestal ineens naar een andere locatie scroll-wise"). Deze twee regels
 *  stonden in `Invoer` — het inline TITELveld — en nergens anders: de combobox
 *  (`IriCombobox.openBewerk`) en het heropenen van een al open inline veld
 *  (`InlineVeld.openBewerk`) deden een KALE `focus()`. De browser scrollt daarbij
 *  zelf, en niet minimaal: gemeten op de gebouwde app schoof de pagina 427px toen
 *  de sloteditor van een verse voorwaarde opende terwijl de ghost onderin het
 *  venster stond (scrollY 308 → 735). De Δ0-poort zag dat niet, want die meet één
 *  scenario: een kaart-ghost halverwege het venster, waar een kale `focus()`
 *  toevallig niets doet omdat het veld al zichtbaar is.
 *
 *  DE DRIE STAPPEN, in deze volgorde:
 *   0. de lezer eerst terugzetten waar hij stond toen hij klikte — zie hieronder;
 *   1. `preventScroll` haalt de sprong van de browser weg;
 *   2. `block: 'nearest'` doet daarna NIETS zolang het veld al in beeld staat —
 *      het normale geval — en schuift anders precies genoeg om het te tonen.
 *      Niet géén scroll dus: een cursor in een veld dat je niet ziet is erger dan
 *      een paar pixels beweging.
 *
 *  WAAROM STAP 0 ERBIJ KWAM (14 sep 2026, lane/taal-dropdown §6a). Stap 2 is
 *  alleen onschuldig als de scrollstand bij binnenkomst nog klopt, en dat is
 *  niet gegarandeerd: sloopt de herrender het element dat de focus had, dan
 *  scrolt Chromium in datzelfde frame uit zichzelf weg — een kaal `scroll`-event
 *  dat in een val op álle programmeerbare scrollwegen geen enkele aanroep uit de
 *  app boven zich heeft. Vanaf díe stand denkt `nearest` vervolgens dat het veld
 *  onder het venster ligt, en lijnt het keurig uit op een plek waar de lezer
 *  nooit heeft gestaan (gemeten: 1581 -> 270 -> 1130).
 *
 *  De toets "staat het veld al in beeld?" is daarvoor géén oplossing: op dat
 *  moment stáát het er niet meer in. De juiste vraag is niet waar het veld is
 *  maar waar de LEZER was, en dat is precies wat `herstelLezerplek()` bijhoudt.
 *  Is er niets verschoven, dan doet hij niets. */
export function focusZonderSprong(el: HTMLElement | null | undefined): void {
  if (!el) return;
  herstelLezerplek();
  try { el.focus({ preventScroll: true }); } catch { el.focus(); }
  if (typeof el.scrollIntoView === 'function') {
    el.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  }
}

function Invoer(props: {
  start: string;
  meerregelig?: boolean;
  type?: 'text' | 'date';
  /** DE HINT VAN EEN LEEG VELD — het `placeholder`-attribuut. Zie `InlineVeld`. */
  hint?: string;
  valideer?: (nieuw: string) => boolean;
  opOpslaan: (nieuw: string) => void;
  opAnnuleer: () => void;
  meld: (el: Invoerveld) => void;
}): JSX.Element {
  let el!: Invoerveld;
  // TWEE VLAGGEN, TWEE VERSCHILLENDE DUBBELKLAPPEN:
  //  - geannuleerd: een blur ná Escape mag niet alsnog opslaan. Het veld
  //    verdwijnt na Escape uit de DOM en verliest daarmee zijn focus, en in een
  //    echte browser vuurt dat synchroon een blur op datzelfde element.
  //  - verwerkt: opslaan() is zonder dit vlag niet re-entrant-veilig. De
  //    terugval naar de kijkstand haalt `el` uit de DOM terwijl het nog focus
  //    heeft; de blur die daarop volgt zou opslaan() een TWEEDE keer aanroepen
  //    — met dezelfde waarde, dus een dubbele onSave (straks een dubbele
  //    store-mutatie).
  // Reset gebeurt vanzelf: elke nieuwe bewerkstand maakt een nieuwe Invoer, en
  // dus een verse closure.
  let geannuleerd = false;
  let verwerkt = false;

  function opslaan(): void {
    if (geannuleerd || verwerkt) return;
    const nieuw = el.value;
    // `valideer` zegt of deze invoer ÜBERHAUPT opgeslagen mag worden (bv. een
    // sh:pattern uit een shape). Bij `false` gebeuren er twee dingen NIET: er
    // wordt niet opgeslagen, en het veld klapt niet terug naar de kijkstand.
    // Dat tweede is de reden dat de toets hier zit en niet in onSave: een
    // weigering IN onSave laat het veld dicht met de afgekeurde tekst als
    // waarde — een weergave die iets anders toont dan er in de graaf staat.
    // WAAROM het is afgekeurd, meldt de AANROEPER.
    if (props.valideer && !props.valideer(nieuw)) {
      el.setAttribute('aria-invalid', 'true');
      // Niet `verwerkt` zetten: een volgende poging (Enter na correctie, of de
      // blur die op het wegklikken volgt) moet weer langs deze toets kunnen.
      return;
    }
    verwerkt = true;
    props.opOpslaan(nieuw);
  }

  function annuleren(): void {
    geannuleerd = true;
    props.opAnnuleer();
  }

  const opToets = (e: KeyboardEvent) => {
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      annuleren();
      return;
    }
    if (e.key !== 'Enter') return;
    // `meerregelig` is bewust ANDERS: Enter is daar een newline (een
    // beschrijving van drie zinnen mag niet bij de eerste regelovergang al
    // opslaan); Ctrl/Cmd+Enter of blur slaan op. Zelfde afweging als een
    // chatvenster.
    if (props.meerregelig && !(e.ctrlKey || e.metaKey)) return;
    // preventDefault houdt de toets weg bij een omliggende <summary> die
    // anders omklapt (en bij een <form> die zou submitten).
    e.preventDefault();
    opslaan();
  };

  onMount(() => {
    props.meld(el);
    // FOCUS ZONDER SPRONG — de reden staat bij `focusZonderSprong` hierboven.
    // Zij stond hier voluit; sinds punt 4 van de testronde is zij gedeeld met de
    // twee andere focusplekken, want daar ontbrak zij en dáár sprong de pagina.
    focusZonderSprong(el);
  });

  return (
    <Show
      when={props.meerregelig}
      fallback={(
        <input
          ref={(n) => { el = n; }}
          type={props.type === 'date' ? 'date' : 'text'}
          class="edit-input inline-veld-invoer"
          placeholder={props.hint || undefined}
          value={props.start}
          on:keydown={opToets}
          on:blur={() => opslaan()}
        />
      )}
    >
      <textarea
        ref={(n) => { el = n; }}
        class="edit-input inline-veld-invoer"
        placeholder={props.hint || undefined}
        value={props.start}
        on:keydown={opToets}
        on:blur={() => opslaan()}
      />
    </Show>
  );
}

export function InlineVeld(props: {
  waarde?: string;
  meerregelig?: boolean;
  type?: 'text' | 'date';
  /** DE HINT VAN EEN LEEG VELD, op twee plekken tegelijk (eigenaarsbevinding
   *  9 sep 2026, tweede ronde):
   *
   *   1. in het OPEN veld als `placeholder` — het attribuut dat de browser zelf
   *      weghaalt zodra er getypt wordt. Dat is de hele vraag van de eigenaar:
   *      "subtle hints die verdwijnen als je begint te typen";
   *   2. in de GESLOTEN stand als gedempte tekst, maar alleen als er ook geen
   *      LEESVORM is om te tonen (`leeg`). Zonder dat tweede zou een kaart
   *      zonder beschrijving in de bewerkstand een onzichtbare, nul pixels
   *      brede klikplek krijgen — er is dan niets om het ✎ naast te zetten. */
  hint?: string;
  /** WAT ER IN HET OPEN VELD STAAT ALS DE WAARDE LEEG IS — een VOORSTEL, geen
   *  waarde.
   *
   *  Eén afnemer (lane-knoophergebruik, 9 sep 2026): de "geef een naam
   *  (IRI)"-affordance op een blanke knoop. Daar is de startwaarde de IRI die
   *  `naamSuggestie` uit het omliggende beleid afleidt, en het onderscheid met
   *  `hint` is precies wat de eigenaarsregel van diezelfde dag vraagt: de
   *  GESLOTEN stand toont niets dat er niet staat (daar staat de hint), en het
   *  OPEN veld — dat je alleen ziet nadat je erom vroeg — begint met het
   *  voorstel, te overtypen of weg te halen.
   *
   *  Hij doet NIETS zodra er een echte waarde is: een bestaande waarde overtypen
   *  met een voorstel zou hem weggooien. */
  startWaarde?: string;
  /** WAT ER IN DE GESLOTEN STAND STAAT ALS DE WAARDE LEEG IS. De aanroeper weet
   *  of er een AFGELEIDE naam is om te tonen (een regel heet naar haar actie,
   *  een naamloze kaart naar haar localName); die hoort hier, want zij is
   *  WEERGAVE en geen data — het invoerveld blijft leeg. Zonder afgeleide naam
   *  laat de aanroeper dit weg en valt de gesloten stand terug op `hint`. */
  leeg?: () => JSX.Element;
  valideer?: (nieuw: string) => boolean;
  onSave?: (nieuw: string) => void;
  onCancel?: () => void;
  /** HET VELD STAAT NU ÉCHT OPEN: gemeld vanuit `onMount` van het invoerveld,
   *  dus wanneer de cursor er in staat en het element in de DOM hangt. De
   *  toevoegfocus gebruikt hem om zijn verzoek pas dán op te ruimen; zie
   *  `neemFocusAan` in `ui/bewerk/kaartveld.tsx` voor het gemeten geval waarin
   *  "opruimen zodra een veld het aanneemt" op een weggegooide instantie landde. */
  onOpen?: () => void;
  /** Geen ✎ vlak achter de waarde: de rij draagt haar ✎ in de actiestrook
   *  rechts, en die opent dit veld via `haak`. */
  zonderPotlood?: boolean;
  haak?: (api: VeldHaak) => void;
}): JSX.Element {
  // De getoonde waarde is LOKAAL zodra er is opgeslagen — de aanroeper hoeft
  // niet eerst een store-rondje te maken voordat de kijkstand klopt. Komt er
  // daarna een nieuwe `waarde` binnen (de store is bij), dan wint die: `defer`
  // houdt de eerste render buiten schot.
  const [lokaal, setLokaal] = createSignal(props.waarde ?? '');
  createEffect(on(() => props.waarde, (v) => setLokaal(v ?? ''), { defer: true }));
  const [open, setOpen] = createSignal(false);
  let veld: Invoerveld | undefined;

  const openBewerk = () => {
    // Al open: een tweede ✎-klik zet de cursor terug in het veld en gooit de
    // half getypte invoer NIET weg. Ook hier zonder sprong: het veld staat op
    // dat moment ergens op de pagina, en een kale `focus()` zou het naar het
    // midden van het venster trekken.
    if (open()) { focusZonderSprong(veld); return; }
    setOpen(true);
  };
  props.haak?.({ openBewerk });

  return (
    <span class="inline-veld">
      <Show
        when={open()}
        fallback={(
          <>
            {/* DE GESLOTEN STAND. Drie gevallen, in deze volgorde: er staat een
                waarde (toon hem), er staat er geen maar er is een afgeleide
                leesvorm (toon die — presentatie, geen data), en anders de hint
                gedempt, zodat er een klikbare plek is waar het veld begint. */}
            <Show
              when={lokaal()}
              fallback={(
                <Show when={props.leeg} fallback={<span class="inline-veld-hint">{props.hint}</span>}>
                  {(l) => l()()}
                </Show>
              )}
            >
              <span class="inline-veld-waarde">{lokaal()}</span>
            </Show>
            <Show when={!props.zonderPotlood}>
              <Knop
                label="✎"
                cls="inline-veld-edit"
                ariaLabel={tekst('edit.veldBewerken')}
                onClick={openBewerk}
              />
            </Show>
          </>
        )}
      >
        <Invoer
          start={lokaal() || props.startWaarde || ''}
          meerregelig={props.meerregelig}
          type={props.type}
          hint={props.hint}
          valideer={props.valideer}
          meld={(el) => { veld = el; props.onOpen?.(); }}
          opOpslaan={(nieuw) => {
            setLokaal(nieuw);
            setOpen(false);
            veld = undefined;
            props.onSave?.(nieuw);
          }}
          opAnnuleer={() => {
            setOpen(false);
            veld = undefined;
            props.onCancel?.();
          }}
        />
      </Show>
    </span>
  );
}

// --- De IRI-combobox --------------------------------------------------------
//
// Eén tekstveld met suggesties — GEEN <select>: elke IRI is vrij invulbaar
// (RDF), de suggesties zijn een hulpmiddel, geen keurslijf.
//
// RESOLUTIE van de invoer: een EXACTE match op het LABEL van een optie wint
// (dat is ook wat er in het veld staat na een keuze uit de datalist); alles
// anders gaat door expandIri (curie -> volle IRI via de bekende prefixes; een
// volle IRI/urn blijft ongemoeid).
//
// Dubbele labels: `find` levert de EERSTE match. Op registerschaal is het
// denkbaar dat twee IRI's hetzelfde label dragen; de eerste in de meegegeven
// volgorde wint dan bewust — geen foutmelding, geen ambiguïteitscontrole. Een
// veld dat hierop moet kunnen vertrouwen, geeft liever een IRI/curie als
// startwaarde mee dan een label met een niet-unieke tekst.
//
// VERTAALNOOT — ELK VELD ZIJN EIGEN <datalist>. De bevroren viewer deelde één
// datalist per optie-ARRAY via een WeakMap, en zijn eigen commentaar waarschuwt
// dat de eerst-aangemaakte veld-root dan in de pagina moet blijven staan
// zolang een ander veld ernaar verwijst. Dat is een handmatige DOM-levensduur,
// en precies wat een Solid-component niet heeft: elk veld kan los ontstaan en
// verdwijnen. Vandaar per veld een eigen lijst — mét een uitweg voor wie de
// prijs niet wil betalen: `listId` verwijst naar een datalist die de AANROEPER
// ophangt (één per categorie, boven in de kaart), en dan bouwt dit veld er geen.
/** `extra` is een TWEEDE regel bijschrift naast de curie — vandaag één afnemer:
 *  de HERKOMST van een bestaande regel die je hergebruikt ("uit Aanbod BRP").
 *  Twee regels heten in dit domein makkelijk allebei "Raadplegen", en dan is de
 *  herkomst het enige verschil dat de lezer ziet vóórdat hij kiest. Hij staat
 *  naast `curie` en niet erín, zodat de curie een curie blijft — hij wordt ook
 *  als invoer herkend (`expandIri`), en er iets achter plakken zou dat breken. */
export type IriOptie = { iri: string; label: string; curie?: string; extra?: string };

/** DE TEKST DIE EEN IRI-COMBOBOX TOONT — de spiegel van de resolutie hierboven.
 *
 *  Een keuze uit de datalist zet het LABEL in het veld en de resolutie herkent
 *  dat weer; dus start ook met het label als de huidige waarde in de optielijst
 *  staat. Anders de curie, en anders de kale IRI — alle drie worden
 *  teruggelezen. Omdat de twee helften elkaars spiegelbeeld zijn, horen ze in
 *  hetzelfde bestand: wie de resolutie verandert en deze functie niet, breekt de
 *  round-trip.
 *
 *  Zij stond gedragsidentiek dubbel in `ui/bewerk/kaartveld.tsx` en
 *  `ui/kaart/formulier-bewerk.tsx` (eindreview I-2) — twee lanes die dezelfde
 *  helperset uit doc.js bouwden, in verschillende bestanden en dus zonder
 *  merge-conflict. Hier staat zij één keer, bij de combobox waar zij over gaat. */
export function optieTekst(opties: IriOptie[], iri?: string | null): string {
  if (!iri) return '';
  const o = opties.find((x) => x.iri === iri);
  if (o) return o.label;
  return (curie(iri) as string) || iri;
}

/** HOEVEEL SUGGESTIES ER TEGELIJK IN EEN DATALIST STAAN.
 *
 *  RULING (lane-knoophergebruik, 9 sep 2026). De brief vraagt om een cap "met
 *  een ruling (bv. eerste N treffers, gesorteerd op label)"; dit is die N, en
 *  vijftig is de keuze. Waarom een cap überhaupt: sinds de partijvelden ook de
 *  REGISTER-organisaties aanbieden (`REGISTER_PARTIJ_BASES` in model/edit.js) is
 *  de kandidatenlijst niet meer zo groot als het document maar zo groot als het
 *  register — TOOI alleen al kent ruim driehonderd gemeenten — en een kaart
 *  draagt tientallen velden tegelijk, elk met zijn eigen `<datalist>` (zie de
 *  vertaalnoot hierboven). Zonder cap staan er dan duizenden `<option>`-knopen in
 *  de DOM voor een lijst waarvan de lezer er zes ziet.
 *
 *  WAAROM VIJFTIG EN NIET TIEN OF VIJFHONDERD. Tien is minder dan één
 *  schermvulling van de suggestiedoos in Chrome en zou de lijst laten "trillen"
 *  bij elke toetsaanslag; vijfhonderd haalt het probleem niet weg. Vijftig is
 *  ruim boven wat een dropdown toont en ruim onder wat een DOM-boom merkt.
 *
 *  KOST BIJ ONGELIJK: een lezer die op een lege combobox naar de 51e gemeente
 *  scrollt vindt hem niet — hij moet één letter typen. Dat is precies wat een
 *  combobox is (typen, niet bladeren), en de filter hieronder loopt over de VOLLE
 *  lijst, dus er is geen kandidaat onbereikbaar. */
export const SUGGESTIE_CAP = 50;

/** DE GETOONDE SUGGESTIES: eerst filteren op wat er in het veld staat, dan
 *  afkappen op de cap.
 *
 *  IN DIE VOLGORDE, en dat is de hele reden dat deze functie bestaat. Andersom —
 *  eerst afkappen, dan de browser laten filteren — zou de 51e gemeente
 *  onvindbaar maken, hoeveel je ook typt: een `<datalist>` filtert alleen wat er
 *  in staat. De cap is dus een grens op de WEERGAVE van de treffers, nooit op de
 *  kandidaten.
 *
 *  DRIE VELDEN DOORZOCHT: het label (wat de lezer ziet), de curie (wat hij
 *  intypt als hij het register kent) en de volle IRI (wat er uit een geplakt
 *  adres komt). Hoofdletterongevoelig; de LIJSTVOLGORDE blijft die van de
 *  aanroeper — `termOptions` levert hem op label gesorteerd, dus de cap knipt
 *  alfabetisch en niet willekeurig.
 *
 *  PUUR, en daarom apart toetsbaar zonder DOM: het is een lijst in en een lijst
 *  uit. */
export function filterSuggesties(opties: IriOptie[], invoer: string,
  cap: number = SUGGESTIE_CAP): IriOptie[] {
  const q = String(invoer || '').trim().toLowerCase();
  const treffers = q
    ? opties.filter((o) => o.label.toLowerCase().includes(q)
      || (o.curie || '').toLowerCase().includes(q)
      || (o.extra || '').toLowerCase().includes(q)
      || o.iri.toLowerCase().includes(q))
    : opties;
  return treffers.length > cap ? treffers.slice(0, cap) : treffers;
}

/** WAT ER NAAST HET LABEL VAN EEN OPTIE STAAT: de curie, en daarachter de
 *  `extra` als de aanroeper er een meegeeft. Browsers tonen het `label`-attribuut
 *  van een `<option>` als tweede kolom in de suggestiedoos; dit is die kolom.
 *  Leeg als de curie het label zelf is — dan zou hij zichzelf herhalen. */
function bijschrift(o: IriOptie): string {
  const c = o.curie && o.curie !== o.label ? o.curie : '';
  return [c, o.extra || ''].filter(Boolean).join(' · ');
}

let datalistTeller = 0;

export function IriCombobox(props: {
  options: IriOptie[];
  value?: string;
  placeholder?: string;
  /** Verwijs naar een datalist die de aanroeper zelf ophangt. */
  listId?: string;
  /** De naam van dit veld voor een schermlezer. Een combobox in een KAARTVELD
   *  staat naast zijn leeswaarde en heeft er geen nodig; een combobox in een
   *  FORMULIER (de sloteditor) staat in een labelkolom die de browser niet aan
   *  hem koppelt — daar zegt dit attribuut welk slot je invult. */
  ariaLabel?: string;
  onPick?: (iri: string) => void;
  /** DIT VELD HEEFT DE CURSOR ÉCHT GEKREGEN — dezelfde melding als `onOpen` van
   *  `InlineVeld`, en om dezelfde reden (opruimpunt 22). Een combobox staat
   *  altijd open en heeft dus geen mount-moment om op te wachten; wat haar plaats
   *  inneemt is de toets hieronder: staat het invoerveld in het document, en
   *  heeft het na het focussen ook werkelijk de cursor? Een instantie die na een
   *  herbouw is weggegooid faalt op allebei, en meldt dus niets. */
  onOpen?: () => void;
  haak?: (api: VeldHaak & { waarde: () => string }) => void;
}): JSX.Element {
  datalistTeller += 1;
  const eigenId = `iri-dl-${datalistTeller}`;
  const id = () => props.listId || eigenId;
  let input!: HTMLInputElement;
  // WAT ER OP DIT MOMENT GETYPT STAAT — alleen om de suggesties mee te
  // versmallen. Het veld blijft ONGECONTROLEERD (de waarde komt uit de DOM, zie
  // `huidigeWaarde`): dit signaal is een spiegel, geen bron. Zou het de waarde
  // gaan sturen, dan zou elke toetsaanslag een re-render van het invoerveld
  // veroorzaken en de cursorpositie verzetten.
  const [getypt, zetGetypt] = createSignal('');
  const zichtbaar = () => filterSuggesties(props.options, getypt());

  const huidigeWaarde = () => {
    const inv = input.value;
    const exact = props.options.find((o) => o.label === inv);
    return exact ? exact.iri : (expandIri(inv) as string);
  };

  // Een combobox staat in de bewerkstand al open, dus "bewerken" is hier
  // precies de cursor erin zetten — zelfde haak als bij InlineVeld, en sinds
  // punt 4 van de testronde ook dezelfde sprongvrije focus. DIT was de gemeten
  // springveroorzaker: de sloteditor van een verse voorwaarde opent op de
  // grootheid (`linksHaak.openBewerk()` in sloteditor.tsx), en die kale
  // `focus()` verzette de pagina 427px zodra de ghost onderin het venster stond.
  const openBewerk = () => {
    focusZonderSprong(input);
    // ZIE `onOpen` HIERBOVEN: melden mag alleen wie het ook echt gelukt is. Een
    // losgekoppeld invoerveld (de instantie die de herbouw weggooit) blijft
    // buiten `document` en krijgt de cursor niet — dan is er niets ingelost.
    if (input && input.isConnected && document.activeElement === input) props.onOpen?.();
  };
  props.haak?.({ openBewerk, waarde: huidigeWaarde });

  // Wat Escape terugzet. Ook zonder `onPick` bijgehouden: de terugvalwaarde mag
  // niet afhangen van de vraag of de aanroeper een hook meegaf.
  let geaccepteerd = props.value ?? '';

  return (
    <span class="iri-combobox">
      <input
        ref={(n) => { input = n; }}
        type="text"
        list={id()}
        placeholder={props.placeholder || tekst('edit.iriPlaceholder')}
        aria-label={props.ariaLabel}
        class="edit-input iri-combobox-invoer"
        value={props.value ?? ''}
        on:keydown={(e: KeyboardEvent) => {
          if (e.key === 'Enter') {
            // Zelfde reden als bij InlineVeld: dit veld staat in kaartkoppen en
            // klikbare rijen die anders bij Enter toggelen. Een datalist-keuze
            // breekt hier niet door: de browser zet die waarde al in het veld
            // vóór deze listener draait.
            e.preventDefault();
            return;
          }
          if (e.key !== 'Escape') return;
          // ESCAPE ANNULEERT OOK HIER, symmetrisch met InlineVeld: de invoer
          // gaat terug naar de laatst GEACCEPTEERDE waarde. Een combobox staat
          // permanent open en heeft geen kijkstand om naar terug te vallen —
          // maar half getypte invoer terugnemen moet een lezer wél kunnen, met
          // dezelfde toets als in elk ander veld.
          e.preventDefault();
          e.stopPropagation();
          input.value = geaccepteerd;
        }}
        on:input={() => zetGetypt(input.value)}
        on:change={() => {
          geaccepteerd = input.value;
          props.onPick?.(huidigeWaarde());
        }}
      />
      <Show when={!props.listId}>
        <datalist id={eigenId}>
          <For each={zichtbaar()}>{(o) => (
            // De datalist vult bij selectie het VELD met deze `value` — bewust
            // het LABEL (leesbare tekst), niet de curie: de resolutie hierboven
            // herkent een exacte labelmatch als eerste. De curie staat als
            // `label`-attribuut erbij; dat tonen sommige browsers als hint.
            <option value={o.label} label={bijschrift(o) || undefined} />
          )}</For>
        </datalist>
      </Show>
    </span>
  );
}
