// DE UNIFORME ACTIESTROOK (⠿ ✎ ⧉ ✕) — de rechterkant van elk component dat de
// volle breedte spant: kaartkoppen, regel-/plichtrijen, voorwaarderijen,
// body-rijen en formulierrijen.
//
// Gedragsbron: `actieStrook`, `strookIcoon`, `rovingToetsen` en `slotIcoon` in
// viewer-bevroren/assets/bewerk-ui.js (fase C taak 9b + fix-ronde), en `actieStand` in
// viewer-bevroren/assets/doc.js. De redenen staan daar voluit; hier staat wat er in de
// vertaling naar Solid ANDERS moest.
//
// PUUR. Deze module leest geen bewerkstore en schrijft geen mutatie: de
// aanroeper geeft per icoon een STAND mee (aan/gelockt/uit) en de callback die
// erbij hoort. Welke stand een icoon verdient, beslist de bewerkbaarheidstoets
// van de mutatiekern — de strook kent hem bewust niet (zo is dezelfde strook
// bruikbaar in het document, de verkenner en het invulling-paneel).
//
// VIER VASTE ICONEN IN ÉÉN VASTE VOLGORDE. Een sleutel die de aanroeper
// WEGLAAT levert geen icoon op; dat is hoe de kijkstand (geen enkel icoon) en
// de drie strookvormen zonder ⧉ (voorwaarderij, body-rij, formulierrij) op hun
// aantal uitkomen. NIETS WORDT VERBORGEN: een icoon dat hier niet kan, blijft
// staan met zijn reden in de tooltip.
//
// VERTAALNOOT — `on:click`/`on:keydown`/`on:pointerdown` EN NIET `onClick` c.s.
// Solid DELEGEERT click, keydown en pointerdown naar één listener op het
// document. Een `stopPropagation()` binnen zo'n gedelegeerde handler stopt
// alleen de rest van Solids eigen wandeling — de gebeurtenis heeft het document
// dan al bereikt, en de Escape-/keydown-listeners die dt2 daar rechtstreeks
// ophing (sectiefilter, invulling, zijnav) zijn dus niet meer tegen te houden.
// De fase C-les is juist dat stoppen in de TARGET-fase volstaat én nodig is;
// die les overleeft de migratie alleen met een ECHTE listener op het element,
// en dat is wat de `on:`-vorm oplevert.
import { For, createMemo, createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { tekst } from '../../stores/weergave.js';
import './bewerk.css';

/** Eén van de drie standen van een icoon.
 *  - `{ aan: true, titel, actie }`  — gewoon bedienbaar;
 *  - `{ aan: false, titel, actie }` — GELOCKT: gedimd met een slotje, maar hij
 *    doet nog iets, namelijk de route naar de bewerkbron aanbieden. Daarom
 *    géén aria-disabled: een hulpmiddel dat "uitgeschakeld" voorleest houdt de
 *    gebruiker weg van de enige route die er is;
 *  - `{ aan: false, titel }`        — NIET VAN TOEPASSING: gedimd,
 *    aria-disabled, geen klik. De titel zegt waarom. */
export type IcoonStand = {
  aan: boolean;
  titel?: string;
  actie?: (e?: Event) => void;
  /** Alleen de ⠿: een sleep begint op pointerdown, want een klik komt pas ná
   *  het loslaten en is dan te laat. */
  opPointerDown?: (e: PointerEvent) => void;
};

export type ActieStrookProps = {
  /** Iconen die er al stonden en tot dezelfde rechtergroep horen (⌕ verkennen,
   *  ⚙ invulling). Geen bewerk-affordance; ze staan hier zodat er per rij ÉÉN
   *  rechtergroep is in plaats van twee losse groepjes. */
  voor?: JSX.Element;
  sleep?: IcoonStand;
  bewerk?: IcoonStand;
  dupliceer?: IcoonStand;
  verwijder?: IcoonStand;
  // GEEN `doos` MEER (eigenaarsbesluit 9 sep 2026: "make editable doesn't need a
  // confirmation button"). Hier hing de bak waarin de ontgrendel-dialoog van
  // deze rij opende — een mini-dialoog met "Maak dit de bewerkbron" en
  // "Annuleren". Die tussenstap is vervallen: een gelockt icoon ontgrendelt nu
  // in één klik, en wat de dialoog vóór die klik zei staat sindsdien in de
  // tooltip van datzelfde icoon (zie `actieStand` hieronder). Een bak die nooit
  // meer gevuld wordt is geen restant maar een uitnodiging, dus hij is weg.
  label?: string;
  /** De wortel van de strook (`span.actie-strook`). De bewerklaag gebruikt hem
   *  om vanaf de strook naar de KOPREGEL eromheen te lopen en die als
   *  sleep-drop-zone aan te melden: de zone is de rij, niet de strook, en CSS én
   *  de zone-registry kunnen niet omhoog kijken. Bewust een gewone ref en geen
   *  tweede zone-prop — de strook kent de bronnenlaag niet en hoort dat zo te
   *  houden. */
  ref?: (el: HTMLElement) => void;
};

type Sleutel = 'sleep' | 'bewerk' | 'dupliceer' | 'verwijder';

// ⧉ is ÉÉN glyph (U+29C9). Geen emoji — die valt op een systeem zonder
// emoji-font terug op een leeg blokje, en dan is het signaal juist weg.
const VOLGORDE: { sleutel: Sleutel; teken: string; cls: string; pointer: boolean }[] = [
  { sleutel: 'sleep', teken: '⠿', cls: 'strook-sleep', pointer: true },
  { sleutel: 'bewerk', teken: '✎', cls: 'strook-bewerk', pointer: false },
  { sleutel: 'dupliceer', teken: '⧉', cls: 'strook-dup', pointer: false },
  { sleutel: 'verwijder', teken: '✕', cls: 'strook-weg', pointer: false },
];

/** Het slotje op een gelockte affordance. Een SVG en geen emoji, om dezelfde
 *  reden als in het bronnenpaneel: 🔒 valt zonder emoji-font terug op een leeg
 *  blokje. Woont hier omdat zowel de strook als de ghosts hem dragen. */
export function SlotIcoon(): JSX.Element {
  return (
    <span class="edit-slotje" aria-hidden="true">
      {/* `focusable="false"` via een ref: Solids SVG-typen kennen het attribuut
          niet, maar het hoort er wel te staan — een <svg> is in sommige
          browsers anders een eigen tabstop, en dit slotje zit ín een knop. */}
      <svg
        viewBox="0 0 12 14" width="9" height="11"
        ref={(n: SVGSVGElement) => n.setAttribute('focusable', 'false')}
      >
        <path
          d="M3.3 6.2V4.3a2.7 2.7 0 0 1 5.4 0v1.9"
          fill="none" stroke="currentColor" stroke-width="1.3"
        />
        <rect x="1.6" y="6.2" width="8.8" height="6.6" rx="1.4" fill="currentColor" />
      </svg>
    </span>
  );
}

/** DE STAND VAN ÉÉN ICOON of ghost-optie, uit de toetsen van de aanroeper.
 *
 *  Spec-addendum 6 sep (commit 2b22bb0): er is altijd precies ÉÉN bewerkbare
 *  bron. "Gelockt" heeft daarmee één betekenis — dit leeft niet in DE
 *  bewerkbron — en één antwoord: hiervan (een kopie) de bewerkbron maken. De
 *  drie uitkomsten:
 *    mag                          -> aan;
 *    niet, maar om te schakelen   -> gelockt, met die route;
 *    niet, en niets te schakelen  -> uit, met `nvt` als uitleg.
 *
 *  `nvt` hoort in die derde tak: een grijs icoon zonder reden is precies zo
 *  raadselachtig als een ontbrekend icoon. De uitleg begint met WAT deze knop
 *  is en zegt dan pas waarom hij op slot staat — alleen de slotzin op vier
 *  iconen naast elkaar laat de lezer raden welk icoon hij beet heeft. */
export function actieStand(opts: {
  mag: boolean;
  titel?: string;
  actie?: (e?: Event) => void;
  /** Is er een route om dit alsnog in de bewerkbron te krijgen (lokale kopie
   *  maken, of deze bron de bewerkbron maken)? De aanroeper beslist dat; de
   *  strook kent de bronnenlaag niet. */
  ontgrendelbaar?: boolean;
  /** ONTGRENDELT METEEN (eigenaarsbesluit 9 sep 2026). Tot die datum opende deze
   *  callback een mini-dialoog met een ja/nee-knop; nu doet één klik het werk. */
  opOntgrendel?: (e?: Event) => void;
  /** WAT DIE KLIK GAAT DOEN, in gewone taal: welke bron de bewerkbron wordt, wat
   *  dat de huidige bewerkbron kost, en — als er een kopie geschreven moet
   *  worden — dat commentaar en opmaak daarin verloren gaan. Dit stond tot 9 sep
   *  2026 in de bevestigdialoog, en het staat nu in de tooltip: dezelfde
   *  informatie, op hetzelfde moment (vóór de klik), zonder de handeling erbij.
   *  De aanroeper stelt hem samen — de strook kent de bronnenlaag niet. */
  ontgrendelUitleg?: string;
  nvt?: string;
}): IcoonStand {
  if (opts.mag) return { aan: true, titel: opts.titel, actie: opts.actie };
  if (opts.ontgrendelbaar && opts.opOntgrendel) {
    const reden = [tekst('edit.nietBewerkbron'), opts.ontgrendelUitleg]
      .filter(Boolean).join(' ');
    return {
      aan: false,
      titel: opts.titel ? `${opts.titel} — ${reden}` : reden,
      actie: opts.opOntgrendel,
    };
  }
  return { aan: false, titel: opts.nvt || tekst('edit.geenBewerkbron') };
}

/** WAT DE KLIK OP EEN GELOCKT ICOON GAAT DOEN, in gewone taal.
 *
 *  EIGENAARSBESLUIT 9 SEP 2026 ("make editable doesn't need a confirmation
 *  button"). Deze drie zinnen stonden tot die datum in de ontgrendel-DIALOOG,
 *  vóór de ja/nee-knoppen: welke bron de bewerkbron wordt, wat dat de huidige
 *  bewerkbron kost (er is er maar één — zonder die zin verliest de lezer stil
 *  zijn vorige werkbestand-status), en de opmaakverlies-waarschuwing als er nog
 *  een kopie geschreven moet worden. De dialoog is weg; de zinnen niet. Ze staan
 *  nu in de TOOLTIP van hetzelfde icoon, dus op hetzelfde moment als voorheen —
 *  vóór de klik — maar zonder een handeling te vragen.
 *
 *  HIER EN NIET IN `integratie/stand.tsx`, omdat drie plekken hem nodig hebben:
 *  de stroken en ghosts (via `bewerkStand` daar), het gedimde ✎ op een kaartveld
 *  (`kaartveld.tsx`) en de formulierrijen (`ui/kaart/formulier-bewerk.tsx`).
 *  Die drie deelden de dialoog; ze horen ook de tekst te delen. */
export function ontgrendelUitleg(
  doel: { naam: string; huidige?: string; waarschuw: boolean },
): string {
  return [
    tekst('edit.bewerkbronUitleg', { bron: doel.naam }),
    doel.huidige ? tekst('edit.bewerkbronWisselt', { huidig: doel.huidige }) : '',
    doel.waarschuw ? tekst('src.lockWaarschuwing') : '',
  ].filter(Boolean).join(' ');
}

const isActiveerToets = (e: KeyboardEvent) => e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar';

function stopToets(e: Event): void {
  e.preventDefault();
  e.stopPropagation();
}

export function ActieStrook(props: ActieStrookProps): JSX.Element {
  const refs = new Map<Sleutel, HTMLElement>();
  const [actief, setActief] = createSignal(0);

  const aanwezig = createMemo(() => VOLGORDE
    .map((d) => ({ ...d, spec: props[d.sleutel] }))
    .filter((d): d is typeof d & { spec: IcoonStand } => !!d.spec));

  // TOETSENBORD: ROVING TABINDEX, geen vier losse tabstops. De strook is ÉÉN
  // tabstop (het patroon van een ARIA-toolbar); ← → lopen de iconen langs,
  // Home/End springen naar de randen, Enter/spatie bedient. Vier tabstops per
  // rij zou in een document met honderd rijen vierhonderd tabstops betekenen.
  // De iconen die UIT staan doen mee in de rondgang: hun hele bestaansreden is
  // dat zij hun reden dragen, en die reden hoort ook een toetsenbordgebruiker
  // te bereiken (ARIA-praktijk: focusable, aria-disabled).
  const rij = () => aanwezig().map((d) => refs.get(d.sleutel)).filter(Boolean) as HTMLElement[];
  const naar = (i: number) => {
    const n = aanwezig().length;
    if (!n) return;
    const doel = ((i % n) + n) % n;
    setActief(doel);
    rij()[doel]?.focus();
  };

  return (
    <span
      ref={(el: HTMLElement) => props.ref?.(el)}
      class="actie-strook"
      role="toolbar"
      aria-label={props.label || tekst('edit.strookLabel')}
      on:keydown={(e: KeyboardEvent) => {
        if (e.key === 'ArrowRight') { stopToets(e); naar(actief() + 1); }
        else if (e.key === 'ArrowLeft') { stopToets(e); naar(actief() - 1); }
        else if (e.key === 'Home') { stopToets(e); naar(0); }
        else if (e.key === 'End') { stopToets(e); naar(aanwezig().length - 1); }
      }}
    >
      {props.voor}
      <For each={aanwezig()}>{(d, index) => {
        // `aan` is de POORT voor de sleep, niet alleen voor de stijl: een greep
        // die uit of gelockt staat mag geen sleep kunnen starten. Een gelockte
        // greep hoort de route naar de bewerkbron te bieden, niet een
        // verplaatsing die de bron daarna weigert.
        const sleepFn = () => (d.spec.aan && d.pointer && d.spec.opPointerDown
          ? d.spec.opPointerDown : null);
        const heeftActie = () => !!sleepFn() || typeof d.spec.actie === 'function';
        const klasse = () => ['strook-knop', d.cls,
          d.spec.aan ? '' : (heeftActie() ? 'gelockt' : 'actie-uit'),
          sleepFn() ? 'drag-handle' : ''].filter(Boolean).join(' ');
        const stil = () => !d.spec.aan && !heeftActie();
        return (
          <span
            ref={(el: HTMLElement) => refs.set(d.sleutel, el)}
            class={klasse()}
            role="button"
            tabindex={index() === actief() ? '0' : '-1'}
            title={d.spec.titel}
            // De uitleg staat in `title` (muis) én in `aria-label`
            // (voorlezen). De ⠿ krijgt er alleen in de voorleesvorm zijn
            // toetsenbordgrens bij: een focusbaar icoon dat op geen enkele
            // toets reageert en niet zegt waarom is raadselachtig.
            aria-label={d.spec.titel && sleepFn()
              ? `${d.spec.titel} — ${tekst('edit.sleepGreepToets')}` : d.spec.titel}
            aria-disabled={stil() ? 'true' : undefined}
            on:focus={() => setActief(index())}
            on:pointerdown={(e: PointerEvent) => {
              const fn = sleepFn();
              if (!fn) return;
              e.stopPropagation();
              fn(e);
            }}
            // stopPropagation/preventDefault is geen detail: deze iconen staan
            // in <summary>-koppen en op rijen die bij elke klik open- of
            // dichtklappen. Zonder dat zou elke bewerkactie de kaart eronder
            // omklappen.
            on:click={(e: MouseEvent) => {
              if (stil() || sleepFn() || !d.spec.actie) return;
              e.preventDefault();
              e.stopPropagation();
              d.spec.actie(e);
            }}
            on:keydown={(e: KeyboardEvent) => {
              if (stil() || sleepFn() || !d.spec.actie) return;
              if (!isActiveerToets(e)) return;
              stopToets(e);
              d.spec.actie(e);
            }}
          >
            {d.teken}
            {!d.spec.aan && heeftActie() ? <SlotIcoon /> : null}
          </span>
        );
      }}</For>
    </span>
  );
}
